const FALLBACK = TRANSLATIONS.zh_CN
const INSTALL_URL = "https://brew.sh"
const RESULT_ICON = {
  ImageType: "svg",
  ImageData: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="#C97B2A"/><path d="M8 12h10M8 16h16M8 20h8" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg>'
}
const ACTION_EXECUTE = { ImageType: "svg", ImageData: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--wox-theme-icon-color)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2 4.5 13.5h5.5L9 22l10-13h-6z"/></svg>' }
const ACTION_OPEN = { ImageType: "svg", ImageData: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--wox-theme-icon-color)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 5h5v5M19 5l-9 9"/><path d="M13 7H6a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h9a2 2 0 0 0 2-2v-7"/></svg>' }
const ACTION_SEARCH = { ImageType: "svg", ImageData: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--wox-theme-icon-color)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>' }

const pluginState = {
  api: null,
  labels: null,
  brewPathSetting: ""
}

function tokenize(text) {
  const tokens = []
  const pattern = /"([^"]*)"|'([^']*)'|(\S+)/g
  let match = pattern.exec(text)
  while (match) {
    tokens.push(match[1] != null ? match[1] : match[2] != null ? match[2] : match[3])
    match = pattern.exec(text)
  }
  return tokens
}

function findCommand(token) {
  const name = String(token || "").toLowerCase()
  return COMMANDS.find((command) => command.id === name || command.aliases.includes(name)) || null
}

function parseIntent(query) {
  let search = String(query && query.Search || "")
  const declared = String(query && query.Command || "").trim()
  if (declared) search = `${declared} ${search}`.trim()
  else search = search.trim()
  if (!search) return { page: "home", filter: "" }
  const tokens = tokenize(search)
  if (!tokens.length) return { page: "home", filter: "" }
  const command = findCommand(tokens[0])
  if (!command) return { page: "home", filter: search }
  return { page: "command", command, typed: tokens[0], args: tokens.slice(1) }
}

function triggerOf(query) {
  const text = String(query && query.TriggerKeyword || "brew").trim()
  return text || "brew"
}

function labelsOf() {
  return pluginState.labels || FALLBACK
}

function displayToken(token) {
  const text = String(token)
  return /^[A-Za-z0-9_@+./:=,-]+$/.test(text) ? text : `'${text.replace(/'/g, `'\\''`)}'`
}

function commandText(args) {
  return ["brew", ...args.map(displayToken)].join(" ")
}

// terminalLine is the text written into the shell. The brew path is absolute so a
// GUI-launched terminal still finds Homebrew when the setting points somewhere else.
function terminalLine(brewPath, args) {
  return [displayToken(brewPath), ...args.map(displayToken)].join(" ")
}

function appleScriptEscape(value) {
  return String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"')
}

function darwinScript(app, line) {
  const escaped = appleScriptEscape(line)
  if (app === "iTerm") {
    return [
      'tell application "iTerm"',
      "activate",
      "if (count of windows) is 0 then",
      "set targetWindow to (create window with default profile)",
      "else",
      "set targetWindow to current window",
      "tell targetWindow to create tab with default profile",
      "end if",
      "tell current session of targetWindow to write text \"" + escaped + "\"",
      "end tell"
    ].join("\n")
  }
  return [
    'tell application "Terminal"',
    "if (count of windows) is 0 then",
    "do script \"" + escaped + "\"",
    "else",
    "do script \"" + escaped + "\" in front window",
    "end if",
    "activate",
    "end tell"
  ].join("\n")
}

function preferredTerminal() {
  const homes = [path.join(os.homedir(), "Applications", "iTerm.app"), "/Applications/iTerm.app"]
  return homes.some((item) => {
    try {
      return fs.existsSync(item)
    } catch (error) {
      return false
    }
  }) ? "iTerm" : "Terminal"
}

function resolveBrew() {
  const custom = String(pluginState.brewPathSetting || "").trim()
  if (custom) return fs.existsSync(custom) ? custom : ""
  const candidates = [
    "/opt/homebrew/bin/brew",
    "/usr/local/bin/brew",
    path.join(os.homedir(), ".linuxbrew", "bin", "brew"),
    "/home/linuxbrew/.linuxbrew/bin/brew"
  ]
  return candidates.find((item) => {
    try {
      return fs.existsSync(item)
    } catch (error) {
      return false
    }
  }) || ""
}

function homeMatch(command, filter) {
  const text = String(filter || "").trim().toLowerCase()
  if (!text) return true
  const fields = [
    command.id,
    ...command.aliases,
    TRANSLATIONS.zh_CN[`home_${command.id}`],
    TRANSLATIONS.en_US[`home_${command.id}`]
  ]
  return fields.some((field) => String(field || "").toLowerCase().startsWith(text))
}

async function notify(ctx, message) {
  if (pluginState.api && pluginState.api.Notify) await pluginState.api.Notify(ctx, message)
}

async function log(ctx, level, message) {
  if (pluginState.api && pluginState.api.Log) await pluginState.api.Log(ctx, level, message)
}

async function changeQuery(ctx, text) {
  if (pluginState.api && pluginState.api.ChangeQuery) {
    await pluginState.api.ChangeQuery(ctx, { QueryType: "input", QueryText: text })
  }
}

function action(name, icon, isDefault, context, runAction, keepOpen) {
  return {
    Name: name,
    Icon: icon,
    IsDefault: isDefault,
    PreventHideAfterAction: keepOpen === true,
    ContextData: context,
    Action: async (ctx) => runAction(ctx)
  }
}

function row(options) {
  const result = {
    Id: options.id,
    Title: options.title,
    SubTitle: options.subtitle || "",
    Icon: RESULT_ICON,
    Score: options.score,
    Actions: options.actions || []
  }
  if (options.identity) result.IdentityKey = options.identity
  return result
}

function openInstallPage() {
  const opener = process.platform === "darwin" ? "open" : "xdg-open"
  const child = spawn(opener, [INSTALL_URL], { detached: true, stdio: "ignore" })
  child.unref()
}

function startProcess(file, args) {
  const child = spawn(file, args, { detached: true, stdio: "ignore" })
  child.on("error", () => {})
  child.unref()
  return child
}

// openInTerminal reuses the terminal the user already has. A new tab is created
// when a window exists, so the command does not interrupt the current session.
async function openInTerminal(ctx, args) {
  const labels = labelsOf()
  const brewPath = resolveBrew()
  if (!brewPath) {
    await notify(ctx, labels.missing_title)
    return false
  }
  const line = terminalLine(brewPath, args)
  try {
    if (process.platform === "darwin") {
      startProcess("osascript", ["-e", darwinScript(preferredTerminal(), line)])
    } else if (!openLinuxTerminal(line)) {
      await notify(ctx, labels.notify_open_failed)
      return false
    }
    if (pluginState.api && pluginState.api.HideApp) await pluginState.api.HideApp(ctx)
    await log(ctx, "Info", `open terminal: ${commandText(args)}`)
    return true
  } catch (error) {
    await notify(ctx, labels.notify_open_failed)
    await log(ctx, "Error", error.message || "open terminal failed")
    return false
  }
}

function openLinuxTerminal(line) {
  const shells = ["/bin/bash", "/bin/sh"]
  const shell = shells.find((item) => fs.existsSync(item)) || "/bin/sh"
  const launches = [
    ["gnome-terminal", ["--", shell, "-lc", line]],
    ["konsole", ["-e", shell, "-lc", line]],
    ["kitty", [shell, "-lc", line]],
    ["x-terminal-emulator", ["-e", shell, "-lc", line]]
  ]
  for (const [file, launchArgs] of launches) {
    if (!fs.existsSync(`/usr/bin/${file}`) && !fs.existsSync(`/bin/${file}`)) continue
    startProcess(file, launchArgs)
    return true
  }
  return false
}

function missingRow(labels) {
  return row({
    id: "missing",
    title: labels.missing_title,
    subtitle: labels.missing_subtitle,
    score: 1,
    actions: [
      action(labels.action_open_install, ACTION_OPEN, true, { kind: "install-help" }, async () => openInstallPage(), false)
    ]
  })
}

function homeRow(command, labels, trigger, score) {
  const context = { kind: "home", command: command.id, trigger }
  return row({
    id: `home:${command.id}`,
    title: labels[`home_${command.id}`],
    subtitle: labels[`usage_${command.id}`],
    score,
    identity: `brew:home:${command.id}`,
    actions: [
      action(labels[`home_${command.id}`], ACTION_SEARCH, true, context, async (ctx) => {
        await changeQuery(ctx, `${trigger || "brew"} ${command.id} `)
      }, true)
    ]
  })
}

// ContextData values have to be strings. The argument list is JSON so names with spaces still restore.
function runContext(args, trigger) {
  return { kind: "run", args: JSON.stringify(args), trigger: trigger || "brew" }
}

function argsFromContext(data) {
  if (!data || typeof data.args !== "string" || !data.args) return []
  try {
    const parsed = JSON.parse(data.args)
    return Array.isArray(parsed) ? parsed.map((item) => String(item)) : []
  } catch (error) {
    return []
  }
}

function runRow(args, labels, trigger, score) {
  return row({
    id: `run:${args.join(" ")}`,
    title: commandText(args),
    subtitle: labels.run_subtitle,
    score,
    identity: `brew:run:${args.join("\u0001")}`,
    actions: [
      action(labels.action_run, ACTION_EXECUTE, true, runContext(args, trigger), async (ctx) => {
        await openInTerminal(ctx, args)
      }, false)
    ]
  })
}

function hintRow(title, subtitle) {
  return row({ id: "hint", title, subtitle, score: 1 })
}

function buildPage(query, labels, brewPath) {
  if (!brewPath) return [missingRow(labels)]
  const intent = parseIntent(query)
  const trigger = triggerOf(query)
  if (intent.page === "home") {
    const matched = COMMANDS.filter((command) => homeMatch(command, intent.filter))
    if (!matched.length) return [row({ id: "empty", title: labels.empty_title, subtitle: labels.empty_subtitle, score: 1 })]
    return matched.map((command, index) => homeRow(command, labels, trigger, 1000 - index))
  }
  const args = [intent.typed, ...intent.args]
  if (intent.command.needsArg && intent.args.length === 0) {
    return [hintRow(labels[`usage_${intent.command.id}`], labels.hint_subtitle)]
  }
  return [runRow(args, labels, trigger, 1000)]
}

function restore(mruData) {
  let data = mruData && mruData.ContextData
  if (typeof data === "string") {
    try {
      data = JSON.parse(data)
    } catch (error) {
      data = null
    }
  }
  if (!data || !data.kind) return null
  const labels = labelsOf()
  const trigger = data.trigger || "brew"
  if (data.kind === "home") {
    const command = findCommand(data.command)
    return command ? homeRow(command, labels, trigger, 1) : null
  }
  const restoredArgs = argsFromContext(data)
  if (data.kind === "run" && restoredArgs.length) return runRow(restoredArgs, labels, trigger, 1)
  return null
}

function toolResult(output) {
  return { Output: output }
}

async function registerTools(ctx) {
  const api = pluginState.api
  if (!api || typeof api.RegisterPluginTool !== "function") return
  try {
    const result = await api.RegisterPluginTool(ctx, {
      Tool: {
        Name: "run_brew",
        Description: "i18n:tool_run",
        InputSchema: {
          type: "object",
          properties: {
            command: { type: "string" },
            args: { type: "array", items: { type: "string" } }
          },
          required: ["command"],
          additionalProperties: false
        },
        OutputSchema: {
          type: "object",
          properties: { opened: { type: "boolean" } },
          required: ["opened"]
        },
        Annotations: { ReadOnly: false, Destructive: true, Idempotent: false, RequiresUI: true }
      },
      Handler: async (toolCtx, option) => {
        const command = option && option.Arguments ? option.Arguments.command : ""
        const extra = option && option.Arguments && Array.isArray(option.Arguments.args) ? option.Arguments.args : []
        if (!findCommand(command)) return { Error: { Code: "INVALID_ARGUMENTS", Message: "unknown brew command" } }
        if (!resolveBrew()) return { Error: { Code: "BREW_NOT_FOUND", Message: labelsOf().missing_title } }
        const opened = await openInTerminal(toolCtx, [String(command), ...extra.map((item) => String(item))])
        return opened ? toolResult({ opened: true }) : { Error: { Code: "TERMINAL_OPEN_FAILED", Message: labelsOf().notify_open_failed } }
      }
    })
    if (result && result.Error) await log(ctx, "Warning", `tool run_brew: ${result.Error.Message || result.Error.Code || ""}`)
  } catch (error) {
    await log(ctx, "Warning", `tool run_brew was not registered: ${error.message}`)
  }
}

async function loadLabels(ctx) {
  const labels = { ...FALLBACK }
  const api = pluginState.api
  if (!api || typeof api.GetTranslation !== "function") return labels
  for (const key of Object.keys(FALLBACK)) {
    try {
      const value = await api.GetTranslation(ctx, key)
      if (value && value !== key) labels[key] = value
    } catch (error) {
      // Keep the bundled wording when a translation is missing.
    }
  }
  return labels
}

const plugin = {
  async init(ctx, params) {
    pluginState.api = params.API
    if (pluginState.api && typeof pluginState.api.GetSetting === "function") {
      pluginState.brewPathSetting = await pluginState.api.GetSetting(ctx, "brew_path") || ""
    }
    pluginState.labels = await loadLabels(ctx)
    if (pluginState.api && typeof pluginState.api.OnSettingChanged === "function") {
      await pluginState.api.OnSettingChanged(ctx, async (_ctx, key, value) => {
        if (key === "brew_path") pluginState.brewPathSetting = value || ""
      })
    }
    if (pluginState.api && typeof pluginState.api.OnMRURestore === "function") {
      await pluginState.api.OnMRURestore(ctx, async (_ctx, mruData) => restore(mruData))
    }
    await registerTools(ctx)
  },
  async query(ctx, query) {
    const labels = labelsOf()
    const brewPath = resolveBrew()
    const results = buildPage(query, labels, brewPath)
    await log(ctx, "Info", `Brew results=${results.length} brew=${brewPath ? "yes" : "no"}`)
    return { Results: results }
  }
}

module.exports = {
  plugin,
  translations: TRANSLATIONS,
  brew: {
    parseIntent,
    commandText,
    terminalLine,
    darwinScript,
    buildPage,
    COMMANDS
  }
}
